    "title": "Mark of Legend",
    "summary": "HERETIC ASTARTES model only (excluding DAMNED models). Once per turn, you can re-roll one Hit roll, one Wound roll or one saving throw made for the bearer.",
    "full": "HERETIC ASTARTES model only (excluding DAMNED models). Once per turn, you can re-roll one Hit roll, one Wound roll or one saving throw made for the bearer.",
    "glossary": "glossary-chaos-space-marines-enhancement-mark-of-legend",
    "rule": "detachment-veterans-of-the-long-war"
