    "title": "CONTEMPTUOUS DISREGARD",
    "summary": "Your opponents Shooting phase or the Fight phase, just after an enemy unit has selected its targets. One HERETIC ASTARTES unit from your army (excluding DAMNED units) that was selected as the target of one or more of the attacking unit’s attacks. Until the attacking unit has finished making its attacks, each time an attack targets your unit, worsen the Armour Penetration characteristic of that attack by 1.",
    "full": "Your opponents Shooting phase or the Fight phase, just after an enemy unit has selected its targets. One HERETIC ASTARTES unit from your army (excluding DAMNED units) that was selected as the target of one or more of the attacking unit’s attacks. Until the attacking unit has finished making its attacks, each time an attack targets your unit, worsen the Armour Penetration characteristic of that attack by 1.",
    "glossary": "glossary-chaos-space-marines-stratagem-contemptuous-disregard",
