    "title": "Mark of the Soul Forges",
    "summary": "HERETIC ASTARTES model only (excluding DAMNED models). Each time the bearer makes an attack, an unmodified Hit roll of 5+ scores a Critical Hit.",
    "full": "HERETIC ASTARTES model only (excluding DAMNED models). Each time the bearer makes an attack, an unmodified Hit roll of 5+ scores a Critical Hit.",
    "glossary": "glossary-chaos-space-marines-enhancement-mark-of-the-soul-forges",
