    "title": "Crown of Worms",
    "summary": "WARPSMITH model only. Add 3\" to the range of the bearer’s Warpsmith, Master of Mechanisms and Enrage Machine Spirits abilities.",
    "full": "WARPSMITH model only. Add 3\" to the range of the bearer’s Warpsmith, Master of Mechanisms and Enrage Machine Spirits abilities.",
    "glossary": "glossary-chaos-space-marines-enhancement-crown-of-worms",
    "rule": "detachment-cult-of-the-arkifane"
