    "title": "PREDATORY PURSUIT",
    "summary": "Your opponent’s Movement phase, just after an enemy unit ends a Normal, Advance or Fall back move. One HERETIC ASTARTES VEHICLE or VASHTORR THE ARKIFANE unit from your army that is within 8\" of that enemy unit and not within Engagement Range of one or more enemy units. Your unit can make a Normal move of up to 6\", but must end that move as close as possible to that enemy unit.",
    "full": "Your opponent’s Movement phase, just after an enemy unit ends a Normal, Advance or Fall back move. One HERETIC ASTARTES VEHICLE or VASHTORR THE ARKIFANE unit from your army that is within 8\" of that enemy unit and not within Engagement Range of one or more enemy units. Your unit can make a Normal move of up to 6\", but must end that move as close as possible to that enemy unit.",
